def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_number_combinations():
    def is_valid(n):
        s = str(n)
        if len(s) != 3:
            return False
        if '0' in s:
            return False
        if len(set(s)) != 3:
            return False
        return True

    result = []
    # The smallest 3‑digit number with distinct non‑zero digits is 123
    for first in range(123, 330):  # 3 * 329 = 987, the largest 3‑digit number using digits 1‑9
        if not is_valid(first):
            continue
        second = first * 2
        third = first * 3
        if second > 987 or third > 987:
            continue
        if is_valid(second) and is_valid(third):
            result.append((first, second, third))
    return result

