def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = []
    first = True
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = ''
        abs_coeff = abs(coeff)
        if first:
            if coeff < 0:
                sign = '-'
            first = False
        else:
            sign = '+' if coeff > 0 else '-'
        coeff_part = ''
        if abs_coeff != 1 or degree == 0:
            coeff_part = str(abs_coeff)
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''
        result.append(f'{sign}{coeff_part}{var_part}')
    if not result:
        return '

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"
    map_enc_to_orig = {}
    map_orig_to_enc = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in map_enc_to_orig:
            if map_enc_to_orig[enc_char] != orig_char:
                return "Failed"
        else:
            if orig_char in map_orig_to_enc:
                return "Failed"
            map_enc_to_orig[enc_char] = orig_char
            map_orig_to_enc[orig_char] = enc_char
    if len(map_enc_to_orig) != 26:
        return "Failed"
    decoded_chars = []
    for ch in message:
        if ch not in map_enc_to_orig:
            return "Failed"
        decoded_chars.append(map_enc_to_orig[ch])
    return "".join(decoded_chars)

def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ''
    index_map = {ch: i for i, ch in enumerate(inorder)}
    def helper(in_start: int, in_end: int, post_start: int, post_end: int) -> str:
        if in_start > in_end:
            return ''
        root = postorder[post_end]
        root_idx = index_map[root]
        left_size = root_idx - in_start
        left_pre = helper(in_start, root_idx - 1, post_start, post_start + left_size - 1) if left_size > 0 else ''
        right_pre = helper(root_idx + 1, in_end, post_start + left_size, post_end - 1) if in_end > root_idx else ''
        return root + left_pre + right_pre
    return helper(0, len(inorder) - 1, 0, len(postorder) - 1)

def string_transformation(A: str, B: str, rules: list) -> int | str:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps if
    possible, otherwise returns "NO ANSWER!".
    """
    if A == B:
        return 0

    max_depth = 10
    queue = [(A, 0)]
    visited = {A}

    while queue:
        current, depth = queue.pop(0)

        if depth >= max_depth:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return depth + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, depth + 1))
                start = idx + 1

    return "NO ANSWER!"

def generate_numbers(n, rules) -> int:
    from collections import deque

    start = str(n)
    visited = {start}
    queue = deque([start])

    # Convert rules to string for easy comparison
    string_rules = [(str(src), str(dst)) for src, dst in rules]

    while queue:
        cur = queue.popleft()
        for src, dst in string_rules:
            # For each occurrence of src digit in cur
            for i, ch in enumerate(cur):
                if ch == src:
                    new_num = cur[:i] + dst + cur[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Dynamic programming table: dp[i] is True if volume i can be achieved
    dp = [False] * (V + 1)
    dp[0] = True

    for vol in volumes:
        if vol > V:
            # Skip items that cannot fit individually
            continue
        # Process in reverse to avoid reuse of the same item
        for i in range(V, vol - 1, -1):
            if dp[i - vol]:
                dp[i] = True

    # Find the largest achievable volume that does not exceed the box capacity
    max_occupied = max(i for i, achievable in enumerate(dp) if achievable)
    # The remaining space is the difference between capacity and occupied volume
    return V - max_occupied

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence lengths ending at each position
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Longest decreasing subsequence lengths starting at each position
    dec = [1] * n
    for i in reversed(range(n)):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Longest bitonic subsequence (increasing then decreasing) length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
